#include "systeminfo.h"
#include "../backlight.h"
#include "../state.h"
#include "../ui.h"
#include "../led.h"
#include <stdio.h>
#include <string.h>
#include <sys/statvfs.h>
#include <sys/utsname.h>
#include <stdlib.h>

static int page_offset=0,selected_line=1,sleep_timer_edit_minutes=-1;
static const int BRIGHTNESS_STEP=5,LINE_H=27,TOP_Y=58,MAX_VISIBLE=12;
typedef struct{char label[64];char value[160];int heading;}InfoLine;
static void add_line(InfoLine*l,int*n,const char*a,const char*v,int h){if(*n>=64)return;snprintf(l[*n].label,sizeof(l[*n].label),"%s",a?a:"");snprintf(l[*n].value,sizeof(l[*n].value),"%s",v?v:"");l[*n].heading=h;(*n)++;}
static void format_uptime(char*out,size_t z){FILE*f=fopen("/proc/uptime","r");double x=0;if(f){fscanf(f,"%lf",&x);fclose(f);}long s=(long)x;int d=s/86400;s%=86400;int h=s/3600;s%=3600;int m=s/60;s%=60;if(d)snprintf(out,z,"%dd %02d:%02d:%02ld",d,h,m,s);else snprintf(out,z,"%02d:%02d:%02ld",h,m,s);}
static void format_memory(char*out,size_t z){FILE*f=fopen("/proc/meminfo","r");unsigned long long t=0,a=0,v;char k[64],u[16];if(f){while(fscanf(f,"%63s %llu %15s",k,&v,u)==3){if(!strcmp(k,"MemTotal:"))t=v;else if(!strcmp(k,"MemAvailable:"))a=v;}fclose(f);}if(!t){snprintf(out,z,"--");return;}snprintf(out,z,"%llu / %llu MB",(t-a)/1024,t/1024);}
static void format_free_space(const char*p,char*out,size_t z){struct statvfs v;if(statvfs(p,&v)!=0){snprintf(out,z,"nicht verfuegbar");return;}unsigned long long t=(unsigned long long)v.f_blocks*v.f_frsize,f=(unsigned long long)v.f_bavail*v.f_frsize;if(t>=1073741824ULL)snprintf(out,z,"%.1f GB frei / %.1f GB",f/1073741824.0,t/1073741824.0);else snprintf(out,z,"%.0f MB frei / %.0f MB",f/1048576.0,t/1048576.0);}
static void format_alsa_device(char*out,size_t z){FILE*f=fopen("/proc/asound/cards","r");char line[256],name[128]="";int card=-1;if(f){while(fgets(line,sizeof(line),f)){int n;char x[128];if(sscanf(line," %d [%127[^]]",&n,x)==2){card=n;snprintf(name,sizeof(name),"%s",x);break;}}fclose(f);}if(card>=0){snprintf(out,z,name[0]?"hw:%d,0  %s":"hw:%d,0",card,name);return;}f=fopen("/proc/asound/pcm","r");if(f){while(fgets(line,sizeof(line),f)){int c,d;if(sscanf(line,"%d-%d:",&c,&d)==2){snprintf(out,z,"hw:%d,%d",c,d);fclose(f);return;}}fclose(f);}snprintf(out,z,"--");}
static void format_audio_output(char*out,size_t z){const char*d=SDL_GetCurrentAudioDriver();int n=SDL_GetNumAudioDevices(0);const char*x=n>0?SDL_GetAudioDeviceName(0,0):NULL;if(x&&*x&&d&&*d)snprintf(out,z,"%s (%s)",x,d);else if(x&&*x)snprintf(out,z,"%s",x);else if(d&&*d)snprintf(out,z,"%s",d);else snprintf(out,z,"--");}
static int build_lines(ScreenContext*c,InfoLine*l){int n=0;char b[160];add_line(l,&n,"SYSTEM","",1);snprintf(b,sizeof(b),"%s",APP_VERSION);add_line(l,&n,"Version",b,0);struct utsname u;if(uname(&u)==0){add_line(l,&n,"Kernel",u.release,0);add_line(l,&n,"Architektur",u.machine,0);add_line(l,&n,"Hostname",u.nodename,0);}format_uptime(b,sizeof(b));add_line(l,&n,"Uptime",b,0);add_line(l,&n,"LEISTUNG","",1);if(*c->cpu_usage>=0)snprintf(b,sizeof(b),"%.0f %%",*c->cpu_usage);else strcpy(b,"--");add_line(l,&n,"CPU",b,0);if(*c->cpu_temperature>=0)snprintf(b,sizeof(b),"%.1f °C",*c->cpu_temperature);else strcpy(b,"--");add_line(l,&n,"CPU-Temperatur",b,0);format_memory(b,sizeof(b));add_line(l,&n,"RAM",b,0);if(*c->ram_usage>=0)snprintf(b,sizeof(b),"%.0f %%",*c->ram_usage);else strcpy(b,"--");add_line(l,&n,"RAM-Auslastung",b,0);add_line(l,&n,"AKKU / AUDIO","",1);if(*c->battery_percent>=0)snprintf(b,sizeof(b),"%d %%",*c->battery_percent);else strcpy(b,"--");add_line(l,&n,"Akku",b,0);add_line(l,&n,"Ladezustand",*c->battery_charging==1?"Laedt":"Entlaedt",0);snprintf(b,sizeof(b),"<  %d %%  >",(volume*100)/MIX_MAX_VOLUME);add_line(l,&n,"Lautstaerke",b,0);format_audio_output(b,sizeof(b));add_line(l,&n,"Audio-Ausgabe",b,0);format_alsa_device(b,sizeof(b));add_line(l,&n,"ALSA-Device",b,0);add_line(l,&n,"Display",is_display_off()?"Aus":"An",0);int br=get_brightness_percent();if(br>=0)snprintf(b,sizeof(b),"<  %d %%  >",br);else strcpy(b,"--");add_line(l,&n,"Helligkeit",b,0);int g=led_get_gpio();if(g>=0)snprintf(b,sizeof(b),"<  %d  >  %s%s",g,led_gpio_is_manual()?"Manuell":"Auto",led_gpio_available(g)?"":" / nicht verfuegbar");else snprintf(b,sizeof(b),"<  Auto  >  nicht erkannt");add_line(l,&n,"LED GPIO",b,0);snprintf(b,sizeof(b),"<  %s  >",led_test_mode()?"An":"Aus");add_line(l,&n,"LED Test",b,0);add_line(l,&n,"WIEDERGABE","",1);snprintf(b,sizeof(b),"<  %s  >",repeat_book?"Wiederholen":"Stop am Ende");add_line(l,&n,"Hoerspielende",b,0);add_line(l,&n,"TIMER","",1);int sh=sleep_timer_edit_minutes>=0?sleep_timer_edit_minutes:*c->sleep_timer_minutes;if(sleep_timer_edit_minutes>=0){if(sh>0)snprintf(b,sizeof(b),"<  %d min  >  A: OK",sh);else snprintf(b,sizeof(b),"<  Aus  >  A: OK");}else if(*c->sleep_timer_active){Uint32 now=SDL_GetTicks(),rem=*c->sleep_timer_end_ticks>now?*c->sleep_timer_end_ticks-now:0;snprintf(b,sizeof(b),"<  %d min  >  %d:%02d",*c->sleep_timer_minutes,(int)(rem/60000),(int)((rem/1000)%60));}else if(*c->sleep_timer_minutes>0)snprintf(b,sizeof(b),"<  %d min  >",*c->sleep_timer_minutes);else snprintf(b,sizeof(b),"<  Aus  >");add_line(l,&n,"Sleeptimer",b,0);if(idle_timer_minutes>0)snprintf(b,sizeof(b),"<  %d min  >",idle_timer_minutes);else snprintf(b,sizeof(b),"<  Aus  >");add_line(l,&n,"Idle-Timer",b,0);if(shutdown_after_tracks>0)snprintf(b,sizeof(b),"<  %d Tracks  >",shutdown_after_tracks);else snprintf(b,sizeof(b),"<  Aus  >");add_line(l,&n,"Shutdown nach Tracks",b,0);snprintf(b,sizeof(b),"<  %s  >",shutdown_at_book_end?"An":"Aus");add_line(l,&n,"Shutdown am Ende",b,0);add_line(l,&n,"SPEICHER","",1);for(int i=0;i<*c->storage_path_count;i++){if(c->storage_paths[i].available)format_free_space(c->storage_paths[i].path,b,sizeof(b));else snprintf(b,sizeof(b),"nicht verfuegbar");add_line(l,&n,c->storage_paths[i].path,b,0);}return n;}
static int find_line(InfoLine*l,int n,const char*s){for(int i=0;i<n;i++)if(!strcmp(l[i].label,s))return i;return -1;}
static int next_selectable(InfoLine*l,int n,int f,int d){int i=f+d;while(i>=0&&i<n){if(!l[i].heading)return i;i+=d;}return f;}
static void keep_visible(int n){int m=n-MAX_VISIBLE;if(m<0)m=0;if(selected_line<page_offset)page_offset=selected_line;if(selected_line>=page_offset+MAX_VISIBLE)page_offset=selected_line-MAX_VISIBLE+1;if(page_offset<0)page_offset=0;if(page_offset>m)page_offset=m;}
static void change_led_gpio(int d){int g=led_get_gpio();if(g<0)g=0;else g+=d;if(g<0)g=0;if(g>511)g=511;led_set_gpio_manual(g);}
static void toggle_repeat_book(void){repeat_book=!repeat_book;save_playback_config();}
static void change_shutdown_tracks(int d){shutdown_after_tracks+=d;if(shutdown_after_tracks<0)shutdown_after_tracks=0;if(shutdown_after_tracks>999)shutdown_after_tracks=999;save_playback_config();}
static void toggle_shutdown_end(void){shutdown_at_book_end=!shutdown_at_book_end;save_playback_config();}
static void change_volume(int d){volume+=d;if(volume<0)volume=0;if(volume>MIX_MAX_VOLUME)volume=MIX_MAX_VOLUME;Mix_VolumeMusic(volume);save_state();}
static void change_brightness(int d){int p=get_brightness_percent();if(p<0)return;p+=d;if(p<10)p=10;if(p>100)p=100;set_brightness_percent(p);}
static void edit_sleep_timer(ScreenContext*c,int d){if(sleep_timer_edit_minutes<0)sleep_timer_edit_minutes=*c->sleep_timer_minutes;sleep_timer_edit_minutes+=d;if(sleep_timer_edit_minutes<SLEEP_MIN_MINUTES)sleep_timer_edit_minutes=SLEEP_MIN_MINUTES;if(sleep_timer_edit_minutes>SLEEP_MAX_MINUTES)sleep_timer_edit_minutes=SLEEP_MAX_MINUTES;}
static void confirm_sleep_timer(ScreenContext*c){if(sleep_timer_edit_minutes<0)return;*c->sleep_timer_minutes=sleep_timer_edit_minutes;if(*c->sleep_timer_minutes==0){*c->sleep_timer_active=0;*c->sleep_timer_end_ticks=0;}else{*c->sleep_timer_active=1;*c->sleep_timer_end_ticks=SDL_GetTicks()+(Uint32)(*c->sleep_timer_minutes*60000);}sleep_timer_edit_minutes=-1;}
static void change_idle_timer(int d){idle_timer_minutes+=d;if(idle_timer_minutes<0)idle_timer_minutes=0;if(idle_timer_minutes>IDLE_TIMER_MAX_MINUTES)idle_timer_minutes=IDLE_TIMER_MAX_MINUTES;save_state();}
void systeminfo_handle_event(ScreenContext*c,const SDL_Event*e){InfoLine l[64];int n=build_lines(c,l);if(selected_line>=n)selected_line=n-1;if(selected_line<0)selected_line=0;if(n>0&&l[selected_line].heading)selected_line=next_selectable(l,n,selected_line,1);if(e->type==SDL_JOYBUTTONDOWN){int b=e->jbutton.button;if(b==BUTTON_B){led_set_test_mode(0);sleep_timer_edit_minutes=-1;page_offset=0;selected_line=1;*c->screen=SCREEN_MENU;return;}if(b==BUTTON_L1){for(int i=0;i<MAX_VISIBLE;i++)selected_line=next_selectable(l,n,selected_line,-1);keep_visible(n);return;}if(b==BUTTON_L2){selected_line=0;while(selected_line<n&&l[selected_line].heading)selected_line++;page_offset=0;return;}if(b==BUTTON_R1){for(int i=0;i<MAX_VISIBLE;i++)selected_line=next_selectable(l,n,selected_line,1);keep_visible(n);return;}if(b==BUTTON_R2){selected_line=n-1;while(selected_line>0&&l[selected_line].heading)selected_line--;keep_visible(n);return;}if(b==BUTTON_DPAD_UP){selected_line=next_selectable(l,n,selected_line,-1);keep_visible(n);return;}if(b==BUTTON_DPAD_DOWN){selected_line=next_selectable(l,n,selected_line,1);keep_visible(n);return;}int gl=find_line(l,n,"LED GPIO"),tl=find_line(l,n,"LED Test"),rl=find_line(l,n,"Hoerspielende"),stl=find_line(l,n,"Shutdown nach Tracks"),sel=find_line(l,n,"Shutdown am Ende"),vl=find_line(l,n,"Lautstaerke"),bl=find_line(l,n,"Helligkeit"),sl=find_line(l,n,"Sleeptimer"),il=find_line(l,n,"Idle-Timer");if(b==BUTTON_A&&selected_line==gl){led_reset_gpio_auto();return;}if(b==BUTTON_A&&selected_line==tl){led_set_test_mode(!led_test_mode());return;}if((b==BUTTON_DPAD_LEFT||b==BUTTON_DPAD_RIGHT)&&selected_line==tl){led_set_test_mode(!led_test_mode());return;}if((b==BUTTON_A||b==BUTTON_DPAD_LEFT||b==BUTTON_DPAD_RIGHT)&&selected_line==rl){toggle_repeat_book();return;}if(b==BUTTON_DPAD_LEFT&&selected_line==stl){change_shutdown_tracks(-1);return;}if(b==BUTTON_DPAD_RIGHT&&selected_line==stl){change_shutdown_tracks(1);return;}if((b==BUTTON_A||b==BUTTON_DPAD_LEFT||b==BUTTON_DPAD_RIGHT)&&selected_line==sel){toggle_shutdown_end();return;}if(b==BUTTON_A&&selected_line==sl){confirm_sleep_timer(c);return;}if(b==BUTTON_DPAD_LEFT&&selected_line==gl){change_led_gpio(-1);return;}if(b==BUTTON_DPAD_RIGHT&&selected_line==gl){change_led_gpio(1);return;}if(b==BUTTON_DPAD_LEFT&&selected_line==vl){change_volume(-VOLUME_STEP);return;}if(b==BUTTON_DPAD_RIGHT&&selected_line==vl){change_volume(VOLUME_STEP);return;}if(b==BUTTON_DPAD_LEFT&&selected_line==bl){change_brightness(-BRIGHTNESS_STEP);return;}if(b==BUTTON_DPAD_RIGHT&&selected_line==bl){change_brightness(BRIGHTNESS_STEP);return;}if(b==BUTTON_DPAD_LEFT&&selected_line==sl){edit_sleep_timer(c,-SLEEP_STEP_MINUTES);return;}if(b==BUTTON_DPAD_RIGHT&&selected_line==sl){edit_sleep_timer(c,SLEEP_STEP_MINUTES);return;}if(b==BUTTON_DPAD_LEFT&&selected_line==il){change_idle_timer(-IDLE_TIMER_STEP_MINUTES);return;}if(b==BUTTON_DPAD_RIGHT&&selected_line==il){change_idle_timer(IDLE_TIMER_STEP_MINUTES);return;}}
if(e->type==SDL_JOYAXISMOTION){if(e->jaxis.axis==AXIS_Y){if(!*c->axis_y_lock&&e->jaxis.value<-AXIS_DEADZONE){selected_line=next_selectable(l,n,selected_line,-1);keep_visible(n);*c->axis_y_lock=1;}else if(!*c->axis_y_lock&&e->jaxis.value>AXIS_DEADZONE){selected_line=next_selectable(l,n,selected_line,1);keep_visible(n);*c->axis_y_lock=1;}if(abs(e->jaxis.value)<AXIS_DEADZONE)*c->axis_y_lock=0;}if(e->jaxis.axis==AXIS_X){int gl=find_line(l,n,"LED GPIO"),tl=find_line(l,n,"LED Test"),rl=find_line(l,n,"Hoerspielende"),stl=find_line(l,n,"Shutdown nach Tracks"),sel=find_line(l,n,"Shutdown am Ende"),vl=find_line(l,n,"Lautstaerke"),bl=find_line(l,n,"Helligkeit"),sl=find_line(l,n,"Sleeptimer"),il=find_line(l,n,"Idle-Timer");if(selected_line==tl){if(!*c->axis_x_lock&&abs(e->jaxis.value)>AXIS_DEADZONE){led_set_test_mode(!led_test_mode());*c->axis_x_lock=1;}}else if(selected_line==rl){if(!*c->axis_x_lock&&abs(e->jaxis.value)>AXIS_DEADZONE){toggle_repeat_book();*c->axis_x_lock=1;}}else if(selected_line==stl){if(!*c->axis_x_lock&&e->jaxis.value<-AXIS_DEADZONE){change_shutdown_tracks(-1);*c->axis_x_lock=1;}else if(!*c->axis_x_lock&&e->jaxis.value>AXIS_DEADZONE){change_shutdown_tracks(1);*c->axis_x_lock=1;}}else if(selected_line==sel){if(!*c->axis_x_lock&&abs(e->jaxis.value)>AXIS_DEADZONE){toggle_shutdown_end();*c->axis_x_lock=1;}}else if(selected_line==gl){if(!*c->axis_x_lock&&e->jaxis.value<-AXIS_DEADZONE){change_led_gpio(-1);*c->axis_x_lock=1;}else if(!*c->axis_x_lock&&e->jaxis.value>AXIS_DEADZONE){change_led_gpio(1);*c->axis_x_lock=1;}}else if(selected_line==vl){if(!*c->axis_x_lock&&e->jaxis.value<-AXIS_DEADZONE){change_volume(-VOLUME_STEP);*c->axis_x_lock=1;}else if(!*c->axis_x_lock&&e->jaxis.value>AXIS_DEADZONE){change_volume(VOLUME_STEP);*c->axis_x_lock=1;}}else if(selected_line==bl){if(!*c->axis_x_lock&&e->jaxis.value<-AXIS_DEADZONE){change_brightness(-BRIGHTNESS_STEP);*c->axis_x_lock=1;}else if(!*c->axis_x_lock&&e->jaxis.value>AXIS_DEADZONE){change_brightness(BRIGHTNESS_STEP);*c->axis_x_lock=1;}}else if(selected_line==sl){if(!*c->axis_x_lock&&e->jaxis.value<-AXIS_DEADZONE){edit_sleep_timer(c,-SLEEP_STEP_MINUTES);*c->axis_x_lock=1;}else if(!*c->axis_x_lock&&e->jaxis.value>AXIS_DEADZONE){edit_sleep_timer(c,SLEEP_STEP_MINUTES);*c->axis_x_lock=1;}}else if(selected_line==il){if(!*c->axis_x_lock&&e->jaxis.value<-AXIS_DEADZONE){change_idle_timer(-IDLE_TIMER_STEP_MINUTES);*c->axis_x_lock=1;}else if(!*c->axis_x_lock&&e->jaxis.value>AXIS_DEADZONE){change_idle_timer(IDLE_TIMER_STEP_MINUTES);*c->axis_x_lock=1;}}if(abs(e->jaxis.value)<AXIS_DEADZONE)*c->axis_x_lock=0;}}}
void systeminfo_render(ScreenContext*c){led_test_tick(SDL_GetTicks());InfoLine l[64];int n=build_lines(c,l),m=n-MAX_VISIBLE;if(m<0)m=0;if(page_offset>m)page_offset=m;keep_visible(n);draw_text(c->renderer,c->font,"System",20,20,c->selected);int y=TOP_Y;for(int i=page_offset;i<n&&i<page_offset+MAX_VISIBLE;i++){if(l[i].heading)draw_text(c->renderer,c->font,l[i].label,25,y,c->selected);else{SDL_Color col=i==selected_line?c->selected:c->gray;draw_text(c->renderer,c->font,l[i].label,35,y,col);draw_text_right(c->renderer,c->font,l[i].value,SCREEN_W-35,y,i==selected_line?c->selected:c->white);}y+=LINE_H;}if(n>MAX_VISIBLE){int th=SCREEN_H-95,hh=(th*MAX_VISIBLE)/n;if(hh<18)hh=18;int travel=th-hh,ty=55+(m?(travel*page_offset)/m:0);SDL_SetRenderDrawColor(c->renderer,70,70,80,255);SDL_Rect rail={SCREEN_W-8,55,2,th};SDL_RenderFillRect(c->renderer,&rail);SDL_SetRenderDrawColor(c->renderer,230,210,70,255);SDL_Rect thumb={SCREEN_W-8,ty,2,hh};SDL_RenderFillRect(c->renderer,&thumb);}draw_text(c->renderer,c->font,"B: Zurueck  A: OK/Auto  Hoch/Runter: Auswahl  Wert: Links/Rechts",20,SCREEN_H-25,c->gray);}
